[{"order":1,"type":"heading","text":"TensorFlow.js Model Porting Tutorial"},{"order":2,"type":"paragraph","text":"Porting a Python-based TensorFlow model to TensorFlow.js (TFJS) allows you to run machine learning inference directly in the browser or in Node.js environments. This guide walks you through exporting, converting, and loading your model."},{"order":3,"type":"subheading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"Python 3.x installed with TensorFlow."},{"order":5,"type":"bullet_point","text":"Node.js and npm installed for running the TFJS model."},{"order":6,"type":"bullet_point","text":"An existing trained TensorFlow SavedModel or Keras H5/keras file."},{"order":7,"type":"subheading","text":"Step 1: Install the TensorFlow.js Converter"},{"order":8,"type":"paragraph","text":"To convert Python models into web-friendly formats, you need the tensorflowjs pip package. Run the following command in your terminal:"},{"order":9,"type":"code","text":"pip install tensorflowjs"},{"order":10,"type":"subheading","text":"Step 2: Convert the Model"},{"order":11,"type":"paragraph","text":"Use the tensorflowjs_converter command-line tool to convert your Keras model into the TFJS Layers format. This generates a model.json file along with a set of binary weight shards."},{"order":12,"type":"code","text":"tensorflowjs_converter --input_format=keras path/to/my_model.h5 path/to/tfjs_target_dir"},{"order":13,"type":"subheading","text":"Step 3: Load and Run the Model in JavaScript"},{"order":14,"type":"paragraph","text":"Once converted, you can import the model into your web application using the TensorFlow.js library. Include the TFJS script in your HTML or install via npm."},{"order":15,"type":"code","text":"import * as tf from '@tensorflow/tfjs';

async function loadAndPredict() {
  const model = await tf.loadLayersModel('http://localhost:8080/tfjs_target_dir/model.json');
  const inputTensor = tf.zeros([1, 224, 224, 3]);
  const prediction = model.predict(inputTensor);
  prediction.print();
}

loadAndPredict();"},{"order":16,"type":"subheading","text":"Conclusion"},{"order":17,"type":"paragraph","text":"You have successfully ported a TensorFlow model to TensorFlow.js. You can now deploy your web application, allowing client-side execution with zero server latency."}]
